style.css:
@-moz-document domain("mezzoscholen.magister.net") {
/* COLORS */
:root {
    --bg: #08070e;
    --panel: rgba(20, 14, 32, .78);
    --purple: #a855ff;
    --red: #ff315b;
    --pink: #e34dff;
    --text: #f4edff;
}

/* BACKGROUND */
html, body {
    background:
      radial-gradient(ellipse at 15% 15%, #40105c 0%, transparent 42%),
      radial-gradient(ellipse at 90% 85%, #4a0c22 0%, transparent 38%),
      #08070e !important;
    color: var(--text) !important;
}

/* GENERAL PANELS */
main, section, article,
[class*="panel"], [class*="card"],
[class*="container"], [class*="content"] {
    background-color: var(--panel) !important;
    color: var(--text) !important;
    border-color: rgba(168, 85, 255, .22) !important;
    backdrop-filter: blur(18px) !important;
}

/* NAVIGATION */
nav, aside, header,
[class*="sidebar"], [class*="navigation"] {
    background: rgba(10, 8, 20, .78) !important;
    backdrop-filter: blur(22px) !important;
    border-color: rgba(168, 85, 255, .35) !important;
}

/* TABS */
[role="tab"], [class*="tab"] {
    background: rgba(120, 45, 180, .12) !important;
    color: #e9d8ff !important;
    border: 1px solid rgba(168, 85, 255, .25) !important;
    border-radius: 12px !important;
    transition: .25s ease !important;
}

[role="tab"]:hover, [class*="tab"]:hover {
    background: rgba(168, 85, 255, .25) !important;
    box-shadow: 0 0 16px #a855ff66 !important;
}

/* BUTTONS */
button, [role="button"] {
    background: linear-gradient(120deg, #7928ca, #c02665) !important;
    color: white !important;
    border: 1px solid #b65aff !important;
    border-radius: 10px !important;
    transition: .25s ease !important;
}

button:hover, [role="button"]:hover {
    box-shadow: 0 0 20px #a855ffaa !important;
    filter: brightness(1.2);
}

/* LINKS */
a {
    color: #c994ff !important;
}

a:hover {
    color: #ff477e !important;
    text-shadow: 0 0 9px #ff315b !important;
}

/* INPUTS */
input, textarea, select {
    background: rgba(15, 10, 25, .85) !important;
    color: white !important;
    border: 1px solid #853ac0 !important;
    border-radius: 9px !important;
}

/* TABLES */
table, tr, td, th {
    color: var(--text) !important;
    border-color: rgba(168, 85, 255, .18) !important;
}

/* SCROLLBAR */
* {
    scrollbar-color: #963dff #100b19;
}

/* TEXT SELECTION */
::selection {
    background: #a855ff;
    color: white;
}
}
